// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {XBORNID} from "../src/XBORNID.sol";

contract InvMutTest is Test {
    XBORNID c;
    function setUp() public { c = new XBORNID(); }
    function testRegression_property() public {
        address owner = address(this);
        vm.prank(owner);
        c.XBornID();
        uint256 expectedRef = 200000000e18;
        uint256 actualBalance = c.balanceOf(owner);
        assertTrue(actualBalance == expectedRef, "Owner balance after XBornID() should be 200000000e18 (reference) but buggy gives 100");
    }
}
